# ═══ MarketGym (frame-skip segments) ═══
from kaggle_environments import make


_PRODUCTS = ["WHEAT", "CARROT", "TOMATO", "STRAWBERRY", "MELON",
             "EGG", "MILK", "WOOL", "FERTILIZER"]
_PREMIUM = ["MELON", "MILK", "STRAWBERRY", "WOOL"]
_BASE_PRICE = {"WHEAT": 25, "CARROT": 35, "TOMATO": 60, "STRAWBERRY": 120,
               "MELON": 250, "EGG": 50, "MILK": 160, "WOOL": 200,
               "FERTILIZER": 100}
_T = {"WHEAT": 400, "CARROT": 450, "TOMATO": 200, "STRAWBERRY": 100,
      "MELON": 300, "EGG": 332, "MILK": 122, "WOOL": 105, "FERTILIZER": 200}
_NE_DIR = ["BAKERY", "PIZZA_SHOP", "BRUNCH_SPOT", "YARN_STORE",
           "ICE_CREAM_SHOP", "PET_CAFE", "SMOOTHIE_SHOP", "FARMERS_MARKET"]

# Sell head layout: policy owns ALL sells, staples included.
SELL_PRODUCTS = ["WHEAT", "FERTILIZER", "STRAWBERRY", "MELON", "MILK", "WOOL"]
N_SELL_HEADS = len(SELL_PRODUCTS)
_SELL_FRACS = [0.0, 0.25, 0.50, 0.75, 1.0]
_LEVELS = np.array(_SELL_FRACS)

_OBS_HIST = 32
_OBS_DIM = 51
SHED_IDX = 28
BANK_IDX = 37

_SHOP_PRODUCTS = {
    "BAKERY": ("EGG", "WHEAT"),
    "PIZZA_SHOP": ("MILK", "TOMATO", "WHEAT"),
    "BRUNCH_SPOT": ("EGG", "WHEAT", "STRAWBERRY"),
    "YARN_STORE": ("WOOL",),
    "ICE_CREAM_SHOP": ("STRAWBERRY", "MILK", "WHEAT"),
    "PET_CAFE": ("CARROT",),
    "SMOOTHIE_SHOP": ("STRAWBERRY", "MILK"),
    "FARMERS_MARKET": ("WHEAT", "CARROT", "TOMATO", "STRAWBERRY"),
}


def _tape_sells_count(t: int) -> int:
    mkt = ((_ACTIONS_RAW[min(max(t, 0), len(_ACTIONS_RAW) - 1)] or {})
           .get("market")) or []
    return sum(1 for o in mkt if len(o) >= 3 and o[0] == "SELL")


# Decision mask: turns where the tape sells, plus front-run trigger turns
# (tape sells next turn), plus the final turn for an end-of-season dump.
_IS_DECISION = [(_tape_sells_count(t) > 0 or _tape_sells_count(t + 1) > 0
                 or t == len(_ACTIONS_RAW) - 1) for t in range(len(_ACTIONS_RAW))]
N_DECISIONS = sum(_IS_DECISION)


# ═══════════════════════════════════════════════════════════════════════
#  RuleMirror — pure-Python port of notebook_v16rc5/main.py reactive layer
# ═══════════════════════════════════════════════════════════════════════
_WEED_REPLAY_STEPS = 8
_FR_ITEMS = ("MELON", "MILK", "STRAWBERRY", "WOOL")


class RuleMirror:
    """Replays _ACTIONS_RAW + weed repair + front-run/repay overlay.

    State is per-instance; create one instance per role (opponent seat /
    teacher) and call .reset() at episode boundaries. ``shed_override``
    replaces obs private shed (engine hides opponent sheds).
    """

    def __init__(self):
        self._fr = {}
        self._weed = {}
        self.reset()

    def reset(self):
        self._fr.clear()
        self._weed.clear()

    # -- helpers (ported verbatim, parameterized by seat/state) ----------
    @staticmethod
    def _tile_at(farm, position):
        try:
            x, y = int(position[0]), int(position[1])
            return (farm.get("tiles") or [])[y][x]
        except (IndexError, TypeError, ValueError, KeyError, AttributeError):
            return "LOCKED"

    def _trace_actor_action(self, step, actor):
        trace = _ACTIONS_RAW[min(max(int(step), 0), len(_ACTIONS_RAW) - 1)] or {}
        if actor == "farmer":
            return list(trace.get("farmer") or ["PASS"])
        hands = trace.get("hands", []) or []
        return list(hands[actor] if actor < len(hands) else ["PASS"])

    def _weed_repair(self, obs, action, step, seat):
        game = self._weed.get(seat)
        if game is None or step == 0 or step < int(game.get("last_step", -1)):
            game = {"last_step": step, "active": {}}
            self._weed[seat] = game
        game["last_step"] = step
        farm = (obs.get("farms") or [])[seat]
        positions = [farm.get("farmer"), *list(farm.get("hands") or [])]
        unit_actions = [action.get("farmer", ["PASS"]),
                        *list(action.get("hands") or [])]
        active = game.setdefault("active", {})

        for actor, txn in list(active.items()):
            index = 0 if actor == "farmer" else int(actor) + 1
            if index >= len(unit_actions):
                active.pop(actor, None)
                continue
            age = step - int(txn["start"])
            if age == 1:
                unit_actions[index] = list(txn["intended"])
            elif 2 <= age <= 1 + _WEED_REPLAY_STEPS:
                unit_actions[index] = self._trace_actor_action(step - 1, actor)
            else:
                active.pop(actor, None)

        for index, (position, intended) in enumerate(zip(positions, unit_actions)):
            actor = "farmer" if index == 0 else index - 1
            if actor in active or not isinstance(intended, list) or not intended:
                continue
            if intended[0] not in ("BUILD_PASTURE", "PLANT"):
                continue
            tile = self._tile_at(farm, position)
            if not isinstance(tile, dict) or tile.get("kind") != "WEED":
                continue
            active[actor] = {"start": step, "intended": list(intended)}
            unit_actions[index] = ["DIG"]

        action["farmer"] = unit_actions[0] if unit_actions else ["PASS"]
        action["hands"] = unit_actions[1:]
        return action

    def _align_hands(self, action, obs, seat):
        expected = len(((obs.get("farms") or [])[seat]).get("hands") or [])
        hands = list(action.get("hands") or [])
        if len(hands) < expected:
            hands.extend([["PASS"] for _ in range(expected - len(hands))])
        action["hands"] = [list(o or ["PASS"]) for o in hands[:expected]]
        return action

    @staticmethod
    def _town_demand_now(obs, item, step):
        demand = 1 if item != "FERTILIZER" and step % 24 == 0 else 0
        if step % 4 != 0:
            return demand
        for shop in (obs.get("town") or {}).get("unlocked_shops") or []:
            products = _SHOP_PRODUCTS.get(shop, ())
            if item in products:
                demand += 2 if len(products) == 1 else 1
        return demand

    @staticmethod
    def _future_quantity(step, item):
        future = step + 1
        if not 0 <= future < len(_ACTIONS_RAW):
            return 0
        return sum(max(0, int(o[2])) for o in
                   ((_ACTIONS_RAW[future] or {}).get("market") or [])
                   if len(o) >= 3 and o[0] == "SELL" and o[1] == item)

    @staticmethod
    def _pickup_reserve(action, item):
        reserve = 0
        for order in [action.get("farmer", ["PASS"]),
                      *list(action.get("hands") or [])]:
            if isinstance(order, (list, tuple)) and len(order) >= 2 \
                    and order[0] == "PICKUP" and order[1] == item:
                try:
                    reserve += max(0, int(order[2])) if len(order) >= 3 else 1
                except (TypeError, ValueError):
                    reserve += 1
        return reserve

    @staticmethod
    def _existing_sell(action, item):
        return sum(max(0, int(o[2])) for o in (action.get("market") or [])
                   if len(o) >= 3 and o[0] == "SELL" and o[1] == item)

    def _repay(self, action, state, step):
        if int(state.get("due_step", -1)) != step:
            return action
        due = {str(k): max(0, int(v)) for k, v in
               dict(state.get("due", {})).items()}
        market = []
        for raw in action.get("market") or []:
            order = list(raw)
            if len(order) >= 3 and order[0] == "SELL" \
                    and order[1] in due and due[order[1]] > 0:
                requested = max(0, int(order[2]))
                reduction = min(requested, due[order[1]])
                requested -= reduction
                due[order[1]] -= reduction
                if requested <= 0:
                    continue
                order[2] = requested
            market.append(order)
        action["market"] = market[:10]
        state["due_step"], state["due"] = -1, {}
        return action

    def _front_run(self, action, obs, state, step, shed):
        moved = {}
        for item in _FR_ITEMS:
            target = self._future_quantity(step, item)
            if target <= 0 or self._town_demand_now(obs, item, step) > 0:
                continue
            stock = max(0, int(shed.get(item, 0) or 0))
            reserve = self._pickup_reserve(action, item) \
                + self._existing_sell(action, item)
            quantity = min(target, max(0, stock - reserve))
            if quantity <= 0:
                continue
            market = [list(o) for o in (action.get("market") or [])]
            existing = next((o for o in market if len(o) >= 3
                             and o[0] == "SELL" and o[1] == item), None)
            if existing is not None:
                existing[2] = max(0, int(existing[2])) + quantity
            elif len(market) < 10:
                market.append(["SELL", item, quantity])
            else:
                continue
            action["market"] = market[:10]
            moved[item] = moved.get(item, 0) + quantity
        if moved:
            state["due_step"] = step + 1
            state["due"] = moved
        return action

    # -- entry point ------------------------------------------------------
    def __call__(self, obs: dict, step: int, seat: int = 0,
                 shed_override: dict | None = None) -> dict:
        step_i = min(max(0, int(step)), len(_ACTIONS_RAW) - 1)
        tape = _ACTIONS_RAW[step_i] or {}
        action = {
            "farmer": list(tape.get("farmer") or ["PASS"]),
            "hands": [list(h or ["PASS"]) for h in (tape.get("hands") or [])],
            "market": [list(m) for m in (tape.get("market") or [])],
        }
        action = self._weed_repair(obs, action, step_i, seat)
        state = self._fr.setdefault(seat, {"last_step": -1, "due_step": -1,
                                           "due": {}})
        if step_i == 0 or step_i < int(state.get("last_step", -1)):
            state = {"last_step": step_i, "due_step": -1, "due": {}}
            self._fr[seat] = state
        state["last_step"] = step_i
        if 0 <= int(state.get("due_step", -1)) < step_i:
            state["due_step"], state["due"] = -1, {}
        action = self._repay(action, state, step_i)
        priv = (obs.get("private") or {})
        shed = dict(shed_override) if shed_override is not None \
            else dict(priv.get("shed") or {})
        action = self._front_run(action, obs, state, step_i, shed)
        return self._align_hands(action, obs, seat)


def sell_quantities(market_orders) -> dict:
    """Collapse a market order list into {product: total SELL qty}."""
    d = {}
    for o in market_orders or []:
        if len(o) >= 3 and o[0] == "SELL":
            d[o[1]] = d.get(o[1], 0) + int(o[2])
    return d


def non_sell_orders(tape_action) -> list:
    """Tape market orders minus every SELL (policy owns sells in V9)."""
    return [list(o) for o in ((tape_action or {}).get("market") or [])
           if not (len(o) >= 3 and o[0] == "SELL")]


# ═══════════════════════════════════════════════════════════════════════
#  Gym
# ═══════════════════════════════════════════════════════════════════════
class MarketGym:
    """Turnwise-decision gym. RL owns every SELL; tape keeps logistics/buys."""

    def __init__(self, seed=None, opponent: str = "mirror",
                 opp_model_fn=None):
        cfg = {"episodeSteps": 720}
        if seed is not None:
            cfg["seed"] = seed
        self._env = make("kaggriculture", configuration=cfg, debug=False)
        self._seed = seed
        self._opp_mode = opponent  # "pass" | "rand" | "mirror" | "self" | "curriculum"
        self._mirror = RuleMirror()      # opponent replica (seat 1)
        self._teacher = RuleMirror()     # DAgger teacher (seat 0, exact shed)
        self._step = 0
        self._money = 3000.0
        self._history = []
        self._opp_model_fn = opp_model_fn  # callable(obs_tensor) -> (levels, logp, val)
        self._opp_money_before = 3000.0    # initialized in reset()

    # -- lifecycle --------------------------------------------------------
    def reset(self, seed=None):
        s = seed or self._seed
        if s is not None:
            cfg = {"episodeSteps": 720, "seed": s}
            self._env = make("kaggriculture", configuration=cfg, debug=False)
        self._step = 0
        self._money = 3000.0
        self._history = []
        self._mirror.reset()
        self._teacher.reset()
        raw = self._env.reset(num_agents=2)
        self._last_obs = raw[0].observation
        self._opp_money = self._last_obs["farms"][1]["money"]
        self._opp_money_before = self._opp_money
        # Fast-forward to the FIRST decision turn (step 0 is one).
        while self._step < 720 and not self._is_decision(self._step):
            if self._engine_step(None):
                break
        feat = self._encode(self._last_obs)
        self._history.append(feat)
        while len(self._history) < _OBS_HIST:
            self._history.insert(0, np.zeros(_OBS_DIM, dtype=np.float32))
        return np.concatenate(self._history, dtype=np.float32)

    @staticmethod
    def _is_decision(step: int) -> bool:
        return _IS_DECISION[min(step, len(_IS_DECISION) - 1)]

    @staticmethod
    def _estimate_remaining_value(obs, step):
        """Lightweight Potential-Based shaping potential Φ(s): log(bank) +
        sellable inventory value. NOT a value net — purely for reward shaping."""
        me = (obs.get("farms") or [{}])[0]
        money = me.get("money", 3000)
        shed = ((obs.get("private") or {}).get("shed") or {})
        base_prices = {"WHEAT": 25, "FERTILIZER": 100, "STRAWBERRY": 120,
                       "MELON": 250, "MILK": 160, "WOOL": 200}
        inv_val = sum(shed.get(p, 0) * base_prices.get(p, 50) for p in SELL_PRODUCTS)
        return math.log10(max(money, 1)) * 500 + inv_val * 0.5

    # -- opponents --------------------------------------------------------
    def _opp_action(self) -> dict:
        mode = self._opp_mode
        if mode == "rand":
            moves = ["NORTH", "SOUTH", "EAST", "WEST", "PASS"]
            market = []
            if np.random.rand() < 0.15:
                item = _PREMIUM[np.random.randint(0, 4)]
                market.append(["SELL", item, int(np.random.randint(1, 6))])
            return {"farmer": [moves[np.random.randint(0, len(moves))]],
                    "hands": [], "market": market}
        if mode == "mirror":
            shed = self._opp_shed_proxy()
            act = self._mirror(self._opp_view(shed), self._step, seat=1,
                               shed_override=shed)
            return act
        if mode in ("self", "curriculum") and self._opp_model_fn is not None:
            # Model-based opponent: use 32-step history buffer (1632-dim)
            obs_np = np.concatenate(self._history, dtype=np.float32)
            import torch
            obs_t = torch.from_numpy(obs_np).float().unsqueeze(0)
            with torch.no_grad():
                acts, _, _ = self._opp_model_fn(obs_t)
            # Convert sell-level predictions to market SELL orders (proxy shed)
            shed = self._opp_shed_proxy()
            market = []
            for prod_i, level_i in enumerate(acts[0]):
                k = int(level_i.item()) if hasattr(level_i, 'item') else int(level_i)
                if k <= 0:
                    continue
                item = SELL_PRODUCTS[prod_i]
                qty = int(round(_SELL_FRACS[k] * float(shed.get(item, 0))))
                if qty > 0:
                    market.append(["SELL", item, qty])
            return {"farmer": ["PASS"], "hands": [], "market": market[:10]}
        return {"farmer": ["PASS"], "hands": [], "market": []}  # "pass"

    def _opp_shed_proxy(self) -> dict:
        """Opponent sheds are hidden; production is tape-identical, so our
        own shed is the cheapest consistent proxy."""
        priv = self._last_obs.get("private") or {}
        return dict(priv.get("shed") or {})

    def _opp_view(self, shed: dict) -> dict:
        base = self._last_obs
        return {
            "player": 1,
            "farms": base.get("farms") or [{}, {}],
            "market": base.get("market") or {},
            "town": base.get("town") or {},
            "private": {"shed": shed, "seeds": {}, "inventories": []},
        }

    # -- engine stepping ----------------------------------------------------
    def _engine_step(self, rl_levels):
        """One env turn. rl_levels None => tape buys only (no sells).
        Returns done."""
        tape = _ACTIONS_RAW[min(self._step, len(_ACTIONS_RAW) - 1)] or {}
        market = non_sell_orders(tape)
        if rl_levels is not None:
            market = self._apply_rl(market, rl_levels)
        action = {
            "farmer": list(tape.get("farmer") or ["PASS"]),
            "hands": [list(h or ["PASS"]) for h in (tape.get("hands") or [])],
            "market": market[:10],
        }
        result = self._env.step([action, self._opp_action()])
        self._last_market = market
        self._step += 1
        obs_after = result[0].observation
        new_money = obs_after["farms"][0]["money"]
        self._opp_money = obs_after["farms"][1]["money"]
        # PBRS competitive dense reward: my gain − opp gain (clipped)
        my_delta = new_money - self._money
        opp_delta = self._opp_money - self._opp_money_before
        dense = float(np.clip((my_delta - opp_delta) / 5000.0, -1.0, 1.0))
        self._opp_money_before = self._opp_money
        self._money = new_money
        self._last_obs = obs_after
        self._last_dense = dense
        done = (str(result[0].status) == "DONE") or (len(self._env.steps) >= 720)
        return done

    def step(self, rl_levels):
        """Advance ONE DECISION SEGMENT: RL acts at the current decision
        turn, then env fast-forwards to the next decision turn.
        Returns (obs, summed_reward, done, info)."""
        self._engine_step(rl_levels)
        total_r = self._last_dense
        done = (str(self._env.steps[-1][0].status) == "DONE")
        while not done and self._step < 720 \
                and not self._is_decision(min(self._step, 719)):
            self._engine_step(None)
            total_r += self._last_dense
            done = (str(self._env.steps[-1][0].status) == "DONE")
        if self._step >= 720:
            done = True
        sparse = 0.0
        if done:
            sparse = 5.0 if self._money > self._opp_money else (
                0.0 if self._money == self._opp_money else -5.0)
        feat = self._encode(self._last_obs)
        self._history.append(feat)
        if len(self._history) > _OBS_HIST:
            self._history.pop(0)
        od = dict(self._last_obs) if isinstance(self._last_obs, dict) else {}
        od["_agent_market"] = getattr(self, "_last_market", None)
        info = {"money": self._money, "opp_money": self._opp_money,
                "step": self._step,
                "teacher": self._teacher_labels(od)}
        return np.concatenate(self._history, dtype=np.float32), \
            total_r + sparse, done, info

    # -- action application ---------------------------------------------
    def _apply_rl(self, buy_orders, rl_levels):
        """Append policy SELL orders: level k -> round(FRACS[k]*shed) units.
        Engine aborts an order once shed runs dry, so overshoot is safe."""
        shed = ((self._last_obs.get("private") or {}).get("shed")) or {}
        market = [list(o) for o in buy_orders]
        room = 10 - len(market)
        for prod_i, level_i in enumerate(rl_levels):
            k = int(level_i)
            if k <= 0 or room <= 0:
                continue
            item = SELL_PRODUCTS[prod_i]
            qty = int(round(_SELL_FRACS[k] * float(shed.get(item, 0))))
            if qty > 0:
                market.append(["SELL", item, qty])
                room -= 1
        return market[:10]

    # -- teacher ----------------------------------------------------------
    def _teacher_labels(self, obs) -> list:
        """DAgger-style labels at the CURRENT decision turn: what the rule
        layer would sell this turn on our exact shed (front-run included),
        as fraction levels of shed stock. No temporal aggregation."""
        step = max(self._step - 1, 0)
        shed = ((obs.get("private") or {}).get("shed")) or {}
        mirror_now = self._teacher(obs, step, seat=0, shed_override=shed)
        want = sell_quantities(mirror_now.get("market"))
        labels = []
        for p in SELL_PRODUCTS:
            denom = max(int(shed.get(p, 0)), 1)
            frac = float(np.clip(want.get(p, 0) / denom, 0.0, 1.0))
            labels.append(int(np.argmin(np.abs(_LEVELS - frac))))
        return labels

    # -- encoding (layout-compatible with v8) ------------------------------
    def _encode(self, obs):
        d = obs if isinstance(obs, dict) else {}
        me = d.get("farms", [{}])[0]
        opp = d.get("farms", [{}])[1] if len(d.get("farms", [])) > 1 else {}
        priv = d.get("private", {"shed": {}, "seeds": {}})
        mkt = d.get("market", {"inventory": {}, "prices": {}})
        town = d.get("town", {"unlocked_shops": []})
        feat = np.zeros(_OBS_DIM, dtype=np.float32)
        idx = 0
        feat[idx] = self._step / 720.0; idx += 1
        feat[idx] = (self._step % 24) / 24.0; idx += 1
        inv = mkt.get("inventory", {})
        for p in _PRODUCTS:
            feat[idx] = (inv.get(p, 10000) - 10000) / _T.get(p, 300); idx += 1
        prices = mkt.get("prices", {})
        for p in _PRODUCTS:
            feat[idx] = prices.get(p, _BASE_PRICE[p]) / 300.0; idx += 1
        shop_v = np.zeros(8, dtype=np.float32)
        for s in town.get("unlocked_shops", []):
            if s in _NE_DIR:
                shop_v[_NE_DIR.index(s)] = 1.0
        feat[idx:idx+8] = shop_v; idx += 8
        shed = priv.get("shed", {})
        for p in _PRODUCTS:
            feat[idx] = math.log10(max(shed.get(p, 0), 1)) / 3.0; idx += 1
        feat[idx] = math.log10(max(me.get("money", 3000), 1)) / 6.0; idx += 1
        ns = min(self._step + 1, len(_ACTIONS_RAW) - 1)
        tn = _ACTIONS_RAW[ns] or {}
        planned = {}
        for o in tn.get("market", []):
            if len(o) >= 3 and o[0] == "SELL":
                planned[o[1]] = planned.get(o[1], 0) + int(o[2])
        for p in _PRODUCTS:
            feat[idx] = min(planned.get(p, 0), 20) / 20.0; idx += 1
        ot = opp.get("tiles", [])
        oc = sum(1 for r in ot for t in (r or []) if isinstance(t, dict)
                 and t.get("kind") == "PASTURE" and t.get("animal") == "COW")
        os2 = sum(1 for r in ot for t in (r or []) if isinstance(t, dict)
                  and t.get("kind") == "PASTURE" and t.get("animal") == "SHEEP")
        og = sum(1 for r in ot for t in (r or []) if isinstance(t, dict)
                 and t.get("kind") == "COOP" and t.get("animal") == "GOOSE")
        feat[idx] = min(oc, 15) / 15.0; idx += 1
        feat[idx] = min(os2, 10) / 10.0; idx += 1
        feat[idx] = min(og, 8) / 8.0; idx += 1
        feat[idx] = min(oc + os2 + og, 30) / 30.0; idx += 1
        return feat

    def sample_action(self):
        return [int(np.random.randint(0, 5)) for _ in range(N_SELL_HEADS)]

    @property
    def obs_dim(self):
        return _OBS_HIST * _OBS_DIM

    @property
    def n_actions(self):
        return N_SELL_HEADS * 5


def _dummy():
    return {"farmer": ["PASS"], "hands": [], "market": []}


# ═══ TinyTransformer ═══
import math



class CausalSelfAttention(nn.Module):
    """Single-head causal self-attention with mask."""
    def __init__(self, d_model: int, n_heads: int, dropout: float = 0.1):
        super().__init__()
        assert d_model % n_heads == 0
        self.n_heads = n_heads
        self.d_k = d_model // n_heads
        self.qkv = nn.Linear(d_model, 3 * d_model)
        self.proj = nn.Linear(d_model, d_model)
        self.dropout = nn.Dropout(dropout)
        self.d_model = d_model

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        B, S, D = x.shape
        qkv = self.qkv(x).reshape(B, S, 3, self.n_heads, self.d_k)
        qkv = qkv.permute(2, 0, 3, 1, 4)  # (3, B, heads, S, d_k)
        q, k, v = qkv[0], qkv[1], qkv[2]

        # Scaled dot-product attention with causal mask
        scale = 1.0 / math.sqrt(self.d_k)
        scores = torch.matmul(q, k.transpose(-2, -1)) * scale  # (B, heads, S, S)
        
        # Causal mask: only attend to past + current
        causal = torch.triu(torch.ones(S, S, device=x.device, dtype=torch.bool),
                            diagonal=1)
        scores = scores.masked_fill(causal.unsqueeze(0).unsqueeze(0), float('-inf'))
        
        attn = F.softmax(scores, dim=-1)
        attn = self.dropout(attn)
        
        out = torch.matmul(attn, v)  # (B, heads, S, d_k)
        out = out.transpose(1, 2).contiguous().reshape(B, S, D)
        out = self.proj(out)
        return out


class TransformerBlock(nn.Module):
    """Pre-norm transformer block: Attention → FFN."""
    def __init__(self, d_model: int, n_heads: int, d_ff: int = 256, dropout: float = 0.1):
        super().__init__()
        self.attn = CausalSelfAttention(d_model, n_heads, dropout)
        self.norm1 = nn.LayerNorm(d_model)
        self.norm2 = nn.LayerNorm(d_model)
        self.ffn = nn.Sequential(
            nn.Linear(d_model, d_ff),
            nn.GELU(),
            nn.Linear(d_ff, d_model),
            nn.Dropout(dropout),
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x + self.attn(self.norm1(x))
        x = x + self.ffn(self.norm2(x))
        return x


class TinyTransformer(nn.Module):
    """
    Tiny Causal Transformer for market decision making.
    
    Args:
        obs_per_step: feature dim per timestep (51)
        d_model: transformer hidden dim (64)
        n_heads: attention heads (4)
        n_layers: transformer layers (2)
        seq_len: frame stack length (32)
    """
    def __init__(self, obs_per_step=51, d_model=64, n_heads=4,
                 n_layers=2, seq_len=32, n_actions=20):
        super().__init__()
        self.seq_len = seq_len
        self.d_model = d_model
        self.obs_per_step = obs_per_step

        # Embedding: project per-step features to d_model
        self.embed = nn.Linear(obs_per_step, d_model)
        self.pos_enc = nn.Parameter(torch.zeros(1, seq_len, d_model))
        nn.init.trunc_normal_(self.pos_enc, std=0.02)

        # Transformer blocks
        self.blocks = nn.ModuleList([
            TransformerBlock(d_model, n_heads, d_ff=d_model * 4)
            for _ in range(n_layers)
        ])

        # Heads
        self.norm = nn.LayerNorm(d_model)
        self.policy_head = nn.Linear(d_model, n_actions)
        self.value_head = nn.Linear(d_model, 1)

        self._init_weights()

    def _init_weights(self):
        for m in self.modules():
            if isinstance(m, nn.Linear):
                nn.init.orthogonal_(m.weight, gain=1.0)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

    def forward(self, x: torch.Tensor):
        """
        Args:
            x: (B, seq_len * obs_per_step) — flat frame-stack
        Returns:
            logits: (B, n_actions)
            value:  (B, 1)
        """
        B = x.shape[0]
        # Reshape to sequence
        x = x.reshape(B, self.seq_len, self.obs_per_step)  # (B, 32, 51)
        
        # Embed + positional encoding
        h = self.embed(x) + self.pos_enc[:, :self.seq_len]
        
        # Transformer blocks
        for block in self.blocks:
            h = block(h)
        
        h = self.norm(h)
        
        # Use last position for prediction
        last = h[:, -1]  # (B, d_model)
        
        logits = self.policy_head(last)     # (B, 20)
        value = self.value_head(last)       # (B, 1)
        
        return logits, value

    def get_action(self, obs: torch.Tensor, deterministic: bool = False):
        """Sample action given observation."""
        logits, value = self.forward(obs)
        probs = F.softmax(logits, dim=-1)
        if deterministic:
            action = torch.argmax(probs, dim=-1)
        else:
            action = torch.multinomial(probs, 1).squeeze(-1)
        log_prob = F.log_softmax(logits, dim=-1).gather(-1, action.unsqueeze(-1)).squeeze(-1)
        return action, log_prob, value

    def get_action_md(self, obs: torch.Tensor, deterministic: bool = False):
        """MultiDiscrete: independent categoricals over 5 levels each.
        Group count inferred from head width (n_actions // 5).
        Returns actions[N,G], joint_logp[N], value[N]."""
        logits, value = self.forward(obs)
        n_groups = logits.shape[-1] // 5
        acts, logp_sum = [], None
        for k in range(n_groups):
            lg = logits[:, k * 5:(k + 1) * 5]
            dist = torch.distributions.Categorical(logits=lg)
            a = torch.argmax(lg, -1) if deterministic else dist.sample()
            lp = dist.log_prob(a)
            acts.append(a)
            logp_sum = lp if logp_sum is None else logp_sum + lp
        return torch.stack(acts, -1), logp_sum, value.squeeze(-1)

    def count_parameters(self) -> int:
        return sum(p.numel() for p in self.parameters() if p.requires_grad)


# ═══ VecRollout ═══
# persistent pool + async dispatch

import random


def _get_class(name: str):
    """Resolve MarketGym/TinyTransformer whether running standalone
    (module import) or inside a single-file kernel (__main__/__mp_main__)."""
    import sys
    for ns in ("__main__", "__mp_main__"):
        mod = sys.modules.get(ns)
        if mod is not None and hasattr(mod, name):
            return getattr(mod, name)
    # Standalone-module fallback (local dev only)
    mod_name = ("market_gym_v9" if name == "MarketGym"
                else "transformer_model")
    mod = __import__(mod_name, fromlist=[name])
    return getattr(mod, name)


def _worker_main(conn, worker_id: int):
    """Runs inside spawned process. Re-executes host module first (spawn),
    so MarketGym / TinyTransformer globals are available."""
    try:
        import random
        import torch
        import torch.nn.functional as F

        torch.set_num_threads(1)
        model_cls = _get_class("TinyTransformer")
        gym_cls = _get_class("MarketGym")
        model = model_cls(obs_per_step=51, d_model=64, n_heads=4,
                          n_layers=2, seq_len=32, n_actions=30)
        n_groups = 30 // 5
        _curriculum_cache = {}   # path -> model instance
        _opp_pool_paths = []     # current pool paths from parent
        conn.send(("ready", None))
    except Exception:
        conn.send(("fatal", traceback.format_exc()))
        return

    def _get_curriculum_model(path):
        if path not in _curriculum_cache:
            m = model_cls(obs_per_step=51, d_model=64, n_heads=4,
                          n_layers=2, seq_len=32, n_actions=30)
            try:
                sd = np.load(path)
                m.load_state_dict({k: torch.from_numpy(v) for k, v in sd.items()})
            except Exception:
                pass
            m.eval()
            _curriculum_cache[path] = m
        return _curriculum_cache[path].get_action_md

    def play_one(seed: int, opp_pool_paths: list = None):
        # V5 league: mirror 30%, self 30%, curriculum 20%, rand 10%, pass 10%.
        rm = seed % 10
        if rm < 3:
            opp = "mirror"
            opp_cb = None
        elif rm < 6:
            opp = "self"
            opp_cb = model.get_action_md
        elif rm < 8 and opp_pool_paths:
            opp = "curriculum"
            opp_path = random.choice(opp_pool_paths)
            opp_cb = _get_curriculum_model(opp_path)
        elif rm < 9:
            opp = "rand"
            opp_cb = None
        else:
            opp = "pass"
            opp_cb = None
        gym = gym_cls(seed=seed, opponent=opp, opp_model_fn=opp_cb)
        obs = gym.reset()
        buf = {k: [] for k in ("obs", "actions", "rewards", "values",
                               "logps", "dones", "teacher")}
        ep_r, info, done = 0.0, {}, False
        while not done:
            t = torch.from_numpy(obs).unsqueeze(0)
            with torch.no_grad():
                logits, values = model(t)
                acts, lps = [], None
                for k in range(n_groups):
                    lg = logits[:, k * 5:(k + 1) * 5]
                    dist = torch.distributions.Categorical(logits=lg.float())
                    a = dist.sample()
                    lp = dist.log_prob(a)
                    acts.append(a)
                    lps = lp if lps is None else lps + lp
            nxt, r, done, info = gym.step([int(x.item()) for x in acts])
            buf["obs"].append(obs)
            buf["actions"].append([int(x.item()) for x in acts])
            buf["rewards"].append(float(r))
            buf["values"].append(float(values.item()))
            buf["logps"].append(float(lps.item()))
            buf["dones"].append(bool(done))
            buf["teacher"].append(list(info.get("teacher") or [0, 0, 0, 0]))
            ep_r += r
            obs = nxt
        return {
            "obs": np.array(buf["obs"], dtype=np.float32),
            "actions": np.array(buf["actions"], dtype=np.int64),
            "rewards": np.array(buf["rewards"], dtype=np.float32),
            "values": np.array(buf["values"], dtype=np.float32),
            "logps": np.array(buf["logps"], dtype=np.float32),
            "dones": np.array(buf["dones"], dtype=np.bool_),
            "teacher": np.array(buf["teacher"], dtype=np.int64),
            "ep_reward": ep_r,
            "ep_money": info.get("money", 0),
            "ep_opp_money": info.get("opp_money", 0),
            "ep_steps": len(buf["actions"]),
        }

    while True:
        msg = conn.recv()
        if msg[0] == "close":
            conn.close()
            return
        if msg[0] == "run":
            try:
                weights_np, seeds = msg[1], msg[2]
                opp_pool_paths = msg[3] if len(msg) > 3 else []
                _opp_pool_paths[:] = opp_pool_paths
                model.load_state_dict(
                    {k: torch.from_numpy(v) for k, v in weights_np.items()})
                model.eval()
                conn.send(("done", [play_one(s, _opp_pool_paths) for s in seeds]))
            except Exception:
                conn.send(("error", traceback.format_exc()))


class EpisodePool:
    """Persistent worker pool: dispatch(weights, seeds) -> collect()."""

    def __init__(self, n_workers: int, log=print):
        self.n = n_workers
        self.log = log
        self.busy: set[int] = set()
        self.ctx = mp.get_context("spawn")
        self.conns, self.procs = [], []
        t0 = __import__("time").perf_counter()
        for i in range(self.n):
            parent, child = self.ctx.Pipe()
            p = self.ctx.Process(target=_worker_main, args=(child, i), daemon=True)
            p.start()
            child.close()
            tag, payload = parent.recv()
            if tag != "ready":
                self.close()
                raise RuntimeError(f"worker {i} init failed:\n{payload}")
            self.conns.append(parent)
            self.procs.append(p)
        self.log(f"[pool] {self.n} workers ready in "
                 f"{__import__('time').perf_counter()-t0:.1f}s")

    @staticmethod
    def _snapshot(model) -> dict:
        target = model
        if hasattr(target, "module"):        # DataParallel
            target = target.module
        if hasattr(target, "_orig_mod"):     # torch.compile
            target = target._orig_mod
        return {k: v.detach().cpu().numpy().astype(np.float32)
                for k, v in target.state_dict().items()}

    def dispatch(self, model, seeds: list[int], opp_pool_paths: list = None):
        assert not self.busy, "previous batch not collected"
        sd = self._snapshot(model)
        chunks: list[list[int]] = [[] for _ in range(self.n)]
        for i, s in enumerate(seeds):
            chunks[i % self.n].append(s)
        for i in range(self.n):
            if chunks[i]:
                self.conns[i].send(("run", sd, chunks[i], opp_pool_paths or []))
                self.busy.add(i)

    def collect(self) -> list[dict]:
        results: list[dict] = []
        while self.busy:
            conns = [self.conns[i] for i in self.busy]
            c = mp.connection.wait(conns)[0]
            idx = next(i for i in list(self.busy) if self.conns[i] is c)
            tag, payload = c.recv()
            self.busy.discard(idx)
            if tag != "done":
                raise RuntimeError(f"worker {idx} failed:\n{payload}")
            results.extend(payload)
        return results

    def close(self):
        for c in self.conns:
            try:
                c.send(("close",))
            except Exception:
                pass
        for p in self.procs:
            p.join(timeout=3)
            if p.is_alive():
                p.terminate()


def assemble(trajs: list[dict], gamma=0.99, lam=0.95) -> dict:
    batch = {}
    for k in ("obs", "actions", "rewards", "values", "logps", "dones",
              "teacher"):
        batch[k] = np.concatenate([t[k] for t in trajs])
    batch["ep_rewards"] = [t["ep_reward"] for t in trajs]
    batch["ep_money"] = [t["ep_money"] for t in trajs]
    batch["ep_opp_money"] = [t["ep_opp_money"] for t in trajs]
    batch["ep_steps"] = [t["ep_steps"] for t in trajs]

    n = len(batch["rewards"])
    advantages = np.zeros(n, dtype=np.float32)
    returns = np.zeros(n, dtype=np.float32)
    last = 0.0
    for t in reversed(range(n)):
        nv = 0.0 if t == n - 1 else batch["values"][t + 1]
        mask = 1.0 - float(batch["dones"][t])
        delta = batch["rewards"][t] + gamma * nv * mask - batch["values"][t]
        last = delta + gamma * lam * mask * last
        advantages[t] = last
        returns[t] = advantages[t] + batch["values"][t]
    adv = (advantages - advantages.mean()) / (advantages.std() + 1e-8)
    batch["advantages"] = adv.astype(np.float32)
    batch["returns"] = returns.astype(np.float32)
    return batch


# ═══ Training loop ═══
# ═══ CONFIG
# ═══════════════════════════════════════════════════════════════════════
@dataclass
class Config:
    # Model
    obs_per_step: int = 51
    seq_len: int = 32
    d_model: int = 64
    n_heads: int = 4
    n_layers: int = 2
    n_actions: int = 30             # V9: 6 sell heads x 5 levels
    n_policy_groups: int = N_SELL_HEADS

    # GRPO (group-relative baseline, inspired by DeepSeek-R1 / 2502.01652):
    #   When True, replace value head baseline with per-episode group mean.
    #   Useful early in training where value net is noisy.
    grpo_mode: bool = True
    bc_freeze_iters: int = 50

    # Egregore imprinting (competitive bias encoding)
    egregore_use: str = "off"       # "off" | "encode" | "deep"
    egregore_coef: float = 0.15     # weight on egregore policy loss
    egregore_upload: bool = False   # auto-upload best to Kaggle
    egregore_upload_interval: int = 50  # upload every N iters

    # Self-play opponent pool (SPIN-style)
    opp_pool_size: int = 3          # keep last N checkpoints as opponents
    opp_pool_update: int = 25       # update pool every N iters
    opp_pool_iters: list = None     # set in train() based on pool
    opp_pool_paths: list = None     # set in train() based on pool

    # Training
    n_iterations: int = 400          # total PPO iterations
    n_episodes_per_iter: int = 8     # episodes per batch
    rollout_steps: int = 264         # V9: ~258 turnwise decisions per episode
    n_epochs: int = 4                # PPO epochs per batch
    batch_size: int = 64
    lr: float = 3e-4
    lr_final: float = 1e-5           # linear decay target
    clip_eps: float = 0.2
    value_coef: float = 0.5
    entropy_coef: float = 0.02
    entropy_decay: float = 0.9995
    distill_coef: float = 0.20       # OPD: CE toward analytic teacher
    distill_decay: float = 0.995     # λ decay per iteration
    max_grad_norm: float = 0.5
    gamma: float = 0.99
    gae_lambda: float = 0.95

    # Hardware
    device: str = "cuda"
    num_workers: int = 4             # parallel env workers
    compile: bool = True             # torch.compile
    fp16: bool = True                # mixed precision
    use_dataparallel: bool = False   # OFF: 107K-param model; NCCL sync per step
                                     # costs more than it saves on tiny nets.
                                     # Speed already comes from worker pool +
                                     # frame-skip + async pipeline.
    seed: int = 42

    # Logging
    log_interval: int = 1            # every N iterations
    save_interval: int = 25          # checkpoint every N iterations
    eval_interval: int = 50          # promotion gate eval every N
    output_dir: str = "/kaggle/working/rl_output"


cfg = Config()

# ═══════════════════════════════════════════════════════════════════════
#  HARDWARE SETUP
# ═══════════════════════════════════════════════════════════════════════
def setup_device():
    """Probe CUDA with a real kernel; fall back to nvidia-smi check.
    Some Kaggle GPU kernels ship torch+cpu but still expose the device."""
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    # Fallback: nvidia-smi might see the GPU even if torch can't
    if device.type == "cpu":
        try:
            import subprocess as _sp
            smi = _sp.run(["nvidia-smi", "--query-gpu=name,memory.total",
                           "--format=csv,noheader,nounits"],
                          capture_output=True, text=True, timeout=5)
            if smi.returncode == 0 and smi.stdout.strip():
                print(f"🔍 nvidia-smi detected GPU: {smi.stdout.strip()}")
                import os as _os
                _os.environ["CUDA_VISIBLE_DEVICES"] = "0"
                if hasattr(torch, 'cuda') and torch.cuda.device_count() > 0:
                    device = torch.device("cuda")
        except Exception:
            pass

    if device.type == "cuda":
        try:
            _probe = torch.randn(64, 64, device="cuda") @ torch.randn(64, 64,
                                                                     device="cuda")
            torch.cuda.synchronize()
            del _probe
        except Exception as e:
            # Hard fail with full diagnostics (CPU fallback is NOT allowed)
            import subprocess as _sp
            try:
                smi = _sp.run(["nvidia-smi", "--query-gpu=name,compute_cap",
                               "--format=csv"], capture_output=True,
                              text=True, timeout=10).stdout
            except Exception:
                smi = "(nvidia-smi unavailable)"
            raise RuntimeError(
                f"CUDA probe FAILED: {type(e).__name__}: {str(e)[:200]}\n"
                f"torch={torch.__version__} cuda={torch.version.cuda}\n"
                f"gpus={n_gpus} name={torch.cuda.get_device_name(0)} "
                f"cc={torch.cuda.get_device_capability(0)}\n"
                f"nvidia-smi:\n{smi}\n"
                f"-> torch build has no kernels for this GPU; fix "
                f"machine_shape/accelerator, do NOT fall back to CPU"
            )

        n_gpus = torch.cuda.device_count()
        caps = [torch.cuda.get_device_capability(i) for i in range(n_gpus)]
        print(f"🎮 GPU(s): {n_gpus}× {torch.cuda.get_device_name(0)} "
              f"cc={caps[0]}")
        print(f"   VRAM: {torch.cuda.get_device_properties(0).total_memory / 1e9:.1f} GB")

        torch.backends.cuda.matmul.allow_tf32 = True
        torch.backends.cudnn.allow_tf32 = True
        torch.backends.cudnn.benchmark = True
        torch.cuda.set_device(0)
    else:
        print("⚠️  Running on CPU (update phase only — rollouts are in "
              "worker processes)")
    return device


# ═══════════════════════════════════════════════════════════════════════
#  ROLLOUT COLLECTION
# ═══════════════════════════════════════════════════════════════════════
def collect_episode(env: MarketGym, model: nn.Module, device: torch.device,
                    deterministic: bool = False) -> dict:
    """Collect one full episode of experience."""
    obs_list, action_list, reward_list, value_list, logp_list, done_list, teacher_list = \
        [], [], [], [], [], [], []

    obs = env.reset()  # (1632,)
    episode_reward = 0.0

    for step in range(cfg.rollout_steps):
        obs_tensor = torch.from_numpy(obs).float().unsqueeze(0).to(device)
        with torch.no_grad():
            acts, logp, value = model.get_action_md(obs_tensor)
        next_obs, reward, done, info = env.step([int(v) for v in acts[0]])
        episode_reward += reward

        obs_list.append(obs)
        action_list.append([int(v) for v in acts[0]])
        reward_list.append(reward)
        value_list.append(value.item())
        logp_list.append(logp.item())
        done_list.append(done)
        teacher_list.append(list(info.get("teacher") or [0] * (cfg.n_actions // 5)))

        obs = next_obs
        if done:
            break

    return {
        "obs": np.array(obs_list, dtype=np.float32),
        "actions": np.array(action_list, dtype=np.int64),
        "rewards": np.array(reward_list, dtype=np.float32),
        "values": np.array(value_list, dtype=np.float32),
        "logps": np.array(logp_list, dtype=np.float32),
        "dones": np.array(done_list, dtype=np.bool_),
        "teacher": np.array(teacher_list, dtype=np.int64),
        "ep_reward": episode_reward,
        "ep_money": info.get("money", 0),
        "ep_opp_money": info.get("opp_money", 0),
        "ep_steps": len(obs_list),
    }


def collect_batch(n_episodes: int, model: nn.Module, device: torch.device,
                  base_seed: int, deterministic: bool = False,
                  opp_pool_paths: list = None) -> dict:
    """Collect multiple episodes, concatenate into training batch.

    Opponent mix (when pool has entries):
      40% mirror  /  30% pass  /  20% rand  /  10% curriculum (from pool)
    Without pool: mirror only (same as before)."""
    all_data = {"obs": [], "actions": [], "rewards": [], "values": [],
                "logps": [], "dones": [], "ep_rewards": [], "ep_money": [],
                "ep_opp_money": [], "ep_steps": []}

    opp_types = ["mirror", "mirror", "mirror", "pass", "rand"]
    if opp_pool_paths:
        curriculum_type = "curriculum"
        opp_types = ["mirror", "mirror", "pass", "rand", curriculum_type]

    for i in range(n_episodes):
        opp = opp_types[i % len(opp_types)]
        opp_path = None
        if opp == "curriculum" and opp_pool_paths:
            idx = np.random.randint(0, len(opp_pool_paths))
            opp_path = opp_pool_paths[idx]
        env = MarketGym(seed=base_seed + i, opponent=opp,
                        opp_weights_path=opp_path)
        ep_data = collect_episode(env, model, device, deterministic)
        
        for k in all_data:
            if k in ("ep_rewards", "ep_money", "ep_opp_money", "ep_steps"):
                all_data[k].append(ep_data[k])
            else:
                all_data[k].append(ep_data[k])

    # Concatenate all episodes
    batch = {}
    for k in ("obs", "actions", "rewards", "values", "logps", "dones"):
        batch[k] = np.concatenate(all_data[k])
    batch["ep_rewards"] = all_data["ep_rewards"]
    batch["ep_money"] = all_data["ep_money"]
    batch["ep_opp_money"] = all_data["ep_opp_money"]
    batch["ep_steps"] = all_data["ep_steps"]

    # Compute advantages
    if cfg.grpo_mode:
        batch = apply_grpo_baseline(batch)
    else:
        batch["advantages"], batch["returns"] = compute_gae(
            batch["rewards"], batch["values"], batch["dones"]
        )

    # Normalize advantages
    adv = batch["advantages"]
    adv = (adv - adv.mean()) / (adv.std() + 1e-8)
    batch["advantages"] = adv

    return batch


def compute_gae(rewards: np.ndarray, values: np.ndarray, dones: np.ndarray,
                gamma: float = 0.99, lam: float = 0.95) -> Tuple[np.ndarray, np.ndarray]:
    """Compute Generalized Advantage Estimation."""
    n = len(rewards)
    advantages = np.zeros(n, dtype=np.float32)
    returns = np.zeros(n, dtype=np.float32)
    last_gae = 0.0

    for t in reversed(range(n)):
        if t == n - 1:
            next_val = 0.0  # terminal
        else:
            next_val = values[t + 1]
        
        mask = 1.0 - float(dones[t])
        delta = rewards[t] + gamma * next_val * mask - values[t]
        advantages[t] = last_gae = delta + gamma * lam * mask * last_gae
        returns[t] = advantages[t] + values[t]

    return advantages, returns


def apply_grpo_baseline(batch: dict) -> dict:
    """Replace GAE advantages with per-episode group-relative baseline
    (GRPO: arXiv:2502.01652, Hybrid-GRPO).
    
    For each episode in the batch:
      adv[s] = (ep_reward - batch_mean) / batch_std
    All steps within one episode share the same advantage.
    Value loss is zeroed by the caller (set value_coef=0).
    """
    ep_rewards = batch["ep_rewards"]
    ep_steps = batch["ep_steps"]
    rewards = batch["rewards"]
    n = len(rewards)
    
    batch_mean = float(np.mean(ep_rewards))
    batch_std = float(np.std(ep_rewards)) + 1e-8
    
    advantages = np.zeros(n, dtype=np.float32)
    returns = np.zeros(n, dtype=np.float32)
    idx = 0
    for ep_len, ep_r in zip(ep_steps, rewards[:sum(ep_steps)]):
        # Break rewards into per-episode chunks
        ep_r_arr = rewards[idx:idx + ep_len]
        adv_val = (float(np.sum(ep_r_arr)) - batch_mean) / batch_std
        advantages[idx:idx + ep_len] = adv_val
        returns[idx:idx + ep_len] = adv_val  # dummy, unused when value_coef=0
        idx += ep_len
    
    batch["advantages"] = advantages
    batch["returns"] = returns
    return batch


# ═══════════════════════════════════════════════════════════════════════
#  PPO UPDATE
# ═══════════════════════════════════════════════════════════════════════
def ppo_update(model: nn.Module, optimizer: optim.Optimizer,
               scaler: GradScaler, batch: dict, iteration: int,
               entropy_coef: float, distill_coef: float = 0.0,
               egregore_coef: float = 0.0) -> dict:
    """Perform PPO + OPD-distill update over multiple epochs."""
    device = next(model.parameters()).device
    n = len(batch["obs"])

    # Keep dataset on CPU; pin_memory stages H2D copies, loop moves to device.
    obs = torch.from_numpy(batch["obs"])
    actions = torch.from_numpy(batch["actions"]).long()      # [N,4]
    old_logp = torch.from_numpy(batch["logps"])
    advantages = torch.from_numpy(batch["advantages"])
    returns = torch.from_numpy(batch["returns"])
    old_values = torch.from_numpy(batch["values"])
    n_groups = cfg.n_policy_groups
    teacher = torch.from_numpy(batch.get("teacher",
                np.zeros((len(actions), n_groups), dtype=np.int64))).long()

    dataset = TensorDataset(obs, actions, old_logp, advantages, returns,
                            old_values, teacher)
    use_pin = (device.type == "cuda")
    dataloader = DataLoader(dataset, batch_size=cfg.batch_size,
                            shuffle=True, pin_memory=use_pin,
                            drop_last=False, num_workers=0)

    total_policy_loss = 0.0
    total_value_loss = 0.0
    total_entropy = 0.0
    total_clip_frac = 0.0
    total_distill = 0.0
    total_egregore = 0.0
    n_batches = 0

    for epoch in range(cfg.n_epochs):
        for ob, act, olp, adv, ret, oval, tch in dataloader:
            if device.type == "cuda":
                ob = ob.to(device, non_blocking=True)
                act = act.to(device, non_blocking=True)
                olp = olp.to(device, non_blocking=True)
                adv = adv.to(device, non_blocking=True)
                ret = ret.to(device, non_blocking=True)
                oval = oval.to(device, non_blocking=True)
                tch = tch.to(device, non_blocking=True)

            logits, values = model(ob)

            # MultiDiscrete joint logprob / entropy / OPD distill
            new_logp = None
            ent_vec = None
            dist_vec = None
            for k in range(n_groups):
                lg = logits[:, k * 5:(k + 1) * 5]
                dist_k = torch.distributions.Categorical(logits=lg)
                lp_k = dist_k.log_prob(act[:, k])
                new_logp = lp_k if new_logp is None else new_logp + lp_k
                h_k = dist_k.entropy()
                ent_vec = h_k if ent_vec is None else ent_vec + h_k
                d_k = F.cross_entropy(lg, tch[:, k], reduction="none")
                dist_vec = d_k if dist_vec is None else dist_vec + d_k
            entropy = ent_vec.mean()
            distill_mean = dist_vec.mean()

            # Egregore loss: CE toward competitive recommendations (teacher labels)
            egregore_loss = distill_mean.clone() if egregore_coef > 0 else torch.tensor(0.0, device=logits.device)

            # Policy loss
            ratio = (new_logp - olp).exp()
            surr1 = ratio * adv
            surr2 = torch.clamp(ratio, 1.0 - cfg.clip_eps, 1.0 + cfg.clip_eps) * adv
            policy_loss = -torch.min(surr1, surr2).mean()

            # Value loss (clipped) — skipped in GRPO mode (no value baseline)
            if cfg.grpo_mode:
                value_loss = torch.tensor(0.0, device=logits.device)
            else:
                value_loss = F.mse_loss(values.squeeze(-1), ret)
                value_clipped = oval + torch.clamp(
                    values.squeeze(-1) - oval, -cfg.clip_eps, cfg.clip_eps
                )
                value_loss_clipped = F.mse_loss(value_clipped, ret)
                value_loss = 0.5 * torch.max(value_loss, value_loss_clipped)

            # Total loss: PPO + value + entropy + OPD distill + egregore imprint
            loss = (policy_loss + cfg.value_coef * value_loss
                    - entropy_coef * entropy
                    + distill_coef * distill_mean
                    + egregore_coef * egregore_loss)

            # Optimize
            optimizer.zero_grad()
            scaler.scale(loss).backward()
            scaler.unscale_(optimizer)
            nn.utils.clip_grad_norm_(model.parameters(), cfg.max_grad_norm)
            scaler.step(optimizer)
            scaler.update()

            total_policy_loss += policy_loss.item()
            total_value_loss += value_loss.item()
            total_entropy += entropy.item()
            total_distill += distill_mean.item()
            total_egregore += egregore_loss.item()
            clip_frac = ((ratio - 1.0).abs() > cfg.clip_eps).float().mean().item()
            total_clip_frac += clip_frac
            n_batches += 1

    return {
        "policy_loss": total_policy_loss / n_batches,
        "value_loss": total_value_loss / n_batches,
        "entropy": total_entropy / n_batches,
        "clip_frac": total_clip_frac / n_batches,
        "distill_loss": total_distill / n_batches,
        "egregore_loss": total_egregore / n_batches,
    }


# ═══════════════════════════════════════════════════════════════════════
#  HARDWARE MONITORING
# ═══════════════════════════════════════════════════════════════════════
class GPUMonitor:
    """Track GPU memory and utilization during training."""
    def __init__(self):
        self.has_gpu = torch.cuda.is_available()

    def snapshot(self) -> dict:
        if not self.has_gpu:
            return {"gpu_mem_alloc_mb": 0, "gpu_mem_reserved_mb": 0,
                    "gpu_max_alloc_mb": 0}
        with torch.cuda.device(0):
            return {
                "gpu_mem_alloc_mb": torch.cuda.memory_allocated(0) / 1e6,
                "gpu_mem_reserved_mb": torch.cuda.memory_reserved(0) / 1e6,
                "gpu_max_alloc_mb": torch.cuda.max_memory_allocated(0) / 1e6,
            }


# ═══════════════════════════════════════════════════════════════════════
#  CHECKPOINT MANAGEMENT
# ═══════════════════════════════════════════════════════════════════════
def _unwrap_model(model):
    """Peel DataParallel/.module and torch.compile/._orig_mod wrappers."""
    target = model
    if hasattr(target, "module"):
        target = target.module
    if hasattr(target, "_orig_mod"):
        target = target._orig_mod
    return target


def save_checkpoint(model, optimizer, scaler, iteration, best_reward: float,
                    output_dir: str):
    """Save model checkpoint with metadata (always bare TinyTransformer keys)."""
    os.makedirs(output_dir, exist_ok=True)
    ckpt = {
        "iteration": iteration,
        "model_state": _unwrap_model(model).state_dict(),
        "optimizer_state": optimizer.state_dict(),
        "scaler_state": scaler.state_dict(),
        "best_reward": best_reward,
        "config": {
            "obs_per_step": cfg.obs_per_step,
            "seq_len": cfg.seq_len,
            "d_model": cfg.d_model,
            "n_heads": cfg.n_heads,
            "n_layers": cfg.n_layers,
            "n_actions": cfg.n_actions,
        },
    }
    path = os.path.join(output_dir, f"checkpoint_iter{iteration:04d}.pt")
    torch.save(ckpt, path)

    # Also save latest
    latest_path = os.path.join(output_dir, "latest.pt")
    torch.save(ckpt, latest_path)

    # Save best separately
    if iteration > 0:
        best_path = os.path.join(output_dir, "best.pt")
        torch.save(ckpt, best_path)


def load_checkpoint(path: str, model, optimizer, scaler):
    """Resume from checkpoint."""
    ckpt = torch.load(path, map_location="cpu")
    model.load_state_dict(ckpt["model_state"])
    optimizer.load_state_dict(ckpt["optimizer_state"])
    scaler.load_state_dict(ckpt["scaler_state"])
    return ckpt["iteration"], ckpt.get("best_reward", float("-inf"))


# ═══════════════════════════════════════════════════════════════════════
#  LOGGING
# ═══════════════════════════════════════════════════════════════════════
class MetricsLogger:
    """Real-time training metrics with hardware monitoring."""
    def __init__(self, output_dir: str):
        self.output_dir = output_dir
        self.history = []
        self.gpu_monitor = GPUMonitor()
        os.makedirs(output_dir, exist_ok=True)

    def log(self, iteration: int, metrics: dict, timing: dict):
        snapshot = self.gpu_monitor.snapshot()
        entry = {
            "iteration": iteration,
            "timestamp": time.time(),
            **metrics,
            **timing,
            **snapshot,
        }
        self.history.append(entry)

        it = entry["iteration"]
        if not isinstance(it, int) or it % cfg.log_interval == 0:
            self._print(entry)

        # Save rolling log
        with open(os.path.join(self.output_dir, "metrics.jsonl"), "a") as f:
            f.write(json.dumps(entry) + "\n")

    def _print(self, entry: dict):
        gpu_mem = entry.get("gpu_mem_alloc_mb", 0)
        gpu_max = entry.get("gpu_max_alloc_mb", 0)
        iter_label = str(entry.get("iteration", ""))

        print(f"\n{'='*70}")
        print(f"  Iter {iter_label:>6}  |  "
              f"Steps: {entry.get('total_steps', 0):,}  |  "
              f"GPU mem: {gpu_mem:.0f}/{gpu_max:.0f} MB")
        print(f"{'─'*70}")
        print(f"  🏆 Reward")
        print(f"     Mean±Std: {entry.get('mean_reward', 0):>10,.1f} ± {entry.get('std_reward', 0):>8,.1f}")
        print(f"     Best ep:  {entry.get('best_reward', 0):>10,.1f}   |  "
              f"Worst: {entry.get('worst_reward', 0):>10,.1f}")
        print(f"     Money:    {entry.get('mean_money', 0):>10,.0f}  |  "
              f"Opp: {entry.get('mean_opp_money', 0):>10,.0f}")
        print(f"  📊 Training")
        print(f"     Policy:   {entry.get('policy_loss', 0):>10.6f}   |  "
              f"Value: {entry.get('value_loss', 0):>10.6f}")
        print(f"     Entropy:  {entry.get('entropy', 0):>10.6f}   |  "
              f"Clip%: {entry.get('clip_frac', 0):>6.1%}")
        print(f"  ⚡ Speed")
        print(f"     Rollout:  {entry.get('rollout_s', 0):>8.1f}s  |  "
              f"Train: {entry.get('train_s', 0):>8.1f}s")
        print(f"     Steps/s:  {entry.get('steps_per_s', 0):>8.0f}   |  "
              f"Entropy coef: {entry.get('entropy_coef', 0):>8.6f}")
        print(f"     Eps/iter: {entry.get('episodes', 0):>8.0f}   |  "
              f"Ep length: {entry.get('mean_ep_len', 0):>6.0f}")
        print(f"{'='*70}")


# ═══════════════════════════════════════════════════════════════════════
#  MAIN TRAINING LOOP
# ═══════════════════════════════════════════════════════════════════════
def train():
    """Main entry point: train TinyTransformer with PPO on T4."""
    t_start = time.time()

    # Setup
    device = setup_device()
    os.makedirs(cfg.output_dir, exist_ok=True)
    logger = MetricsLogger(cfg.output_dir)

    # Model
    print(f"\n🏗️  Building TinyTransformer...")
    print(f"   Params: seq={cfg.seq_len}, d={cfg.d_model}, "
          f"heads={cfg.n_heads}, layers={cfg.n_layers}")
    
    model = TinyTransformer(
        obs_per_step=cfg.obs_per_step,
        d_model=cfg.d_model,
        n_heads=cfg.n_heads,
        n_layers=cfg.n_layers,
        seq_len=cfg.seq_len,
        n_actions=cfg.n_actions,
    ).to(device)

    if cfg.use_dataparallel and torch.cuda.device_count() > 1:
        model = nn.DataParallel(model)
        print(f"   📦 DataParallel across {torch.cuda.device_count()} GPUs")
    elif torch.cuda.device_count() > 1:
        print(f"   ℹ️  {torch.cuda.device_count()} GPUs present; DP disabled "
              f"(model too small — sync overhead > compute)")

    n_params = model.count_parameters()

    # Opponent pool for self-play distillation
    opp_pool_dir = os.path.join(cfg.output_dir, "opp_pool")
    os.makedirs(opp_pool_dir, exist_ok=True)
    opp_pool_iters = []      # list of iteration numbers in pool
    opp_pool_paths = []      # corresponding file paths

    # Initialize opponent pool with BC weights if available
    bc_path = os.path.join(os.path.dirname(cfg.output_dir) or ".", "bc_init_v9.npz")
    if os.path.exists(bc_path) and len(opp_pool_paths) == 0:
        import shutil
        bc_opp = os.path.join(opp_pool_dir, "iter_bc.npz")
        shutil.copy(bc_path, bc_opp)
        opp_pool_iters.append(-1)
        opp_pool_paths.append(bc_opp)
        print(f"   ♟️  Opponent pool seeded with BC weights")
    print(f"   📊 Parameters: {n_params:,}")
    print(f"   Input dim: {cfg.seq_len * cfg.obs_per_step} → "
          f"Output: {cfg.n_actions}")

    # OPD: initialize from BC warm-start weights if embedded/found
    bc_path = os.path.join(os.path.dirname(cfg.output_dir) or ".",
                           "bc_init_v9.npz")
    if "_BC_WEIGHTS_B64" in globals() and _BC_WEIGHTS_B64:
        import base64 as _b64, io as _io
        raw = zlib.decompress(_b64.b64decode(_BC_WEIGHTS_B64))
        sd = np.load(_io.BytesIO(raw))
        tgt = model.module if hasattr(model, "module") else model
        if hasattr(tgt, "_orig_mod"):
            tgt = tgt._orig_mod
        tgt.load_state_dict({k: torch.from_numpy(sd[k]) for k in sd.files})
        print(f"   🧠 BC warm-start loaded ({len(sd.files)} tensors)")
    elif os.path.exists(bc_path):
        sd = np.load(bc_path)
        tgt = model.module if hasattr(model, "module") else model
        if hasattr(tgt, "_orig_mod"):
            tgt = tgt._orig_mod
        tgt.load_state_dict({k: torch.from_numpy(sd[k]) for k in sd.files})
        print(f"   🧠 BC warm-start loaded from {bc_path}")

    # Freeze BC encoder for first N iters to preserve clone quality
    if cfg.bc_freeze_iters > 0:
        encoder_params = (
            list(model.embed.parameters())
            + [model.pos_enc]
            + list(model.blocks.parameters())
            + list(model.norm.parameters())
        )
        for p in encoder_params:
            p.requires_grad = False
        n_frozen = sum(p.numel() for p in encoder_params)
        print(f"   Encoder frozen ({n_frozen:,} params) for first {cfg.bc_freeze_iters} iters")
        print(f"   Training: policy_head + value_head only")

    # Compile — only when CUDA actually works
    use_cuda = (device.type == "cuda")
    fp16_on = cfg.fp16 and use_cuda
    if cfg.compile and use_cuda and hasattr(torch, 'compile'):
        print("   🔧 torch.compile: ON")
        try:
            model = torch.compile(model, mode="default")
        except Exception as e:
            print(f"   torch.compile unavailable ({type(e).__name__}); eager mode")

    # Optimizer with param groups (encoder frozen at lr=0, policy+value at lr)
    encoder_params = (
        list(model.embed.parameters())
        + [model.pos_enc]
        + list(model.blocks.parameters())
        + list(model.norm.parameters())
    )
    encoder_ids = set(id(p) for p in encoder_params)
    policy_value_params = [p for p in model.parameters() if id(p) not in encoder_ids]
    optimizer = torch.optim.AdamW([
        {"params": encoder_params, "lr": 0.0},
        {"params": policy_value_params},
    ], lr=cfg.lr, weight_decay=1e-4, eps=1e-5)
    n_frozen = sum(p.numel() for p in encoder_params)
    n_train = sum(p.numel() for p in policy_value_params)
    print(f"   Encoder: {n_frozen:,} params (lr=0), Policy+Value: {n_train:,} params")
    scaler = GradScaler(enabled=fp16_on)
    scheduler = torch.optim.lr_scheduler.LinearLR(
        optimizer, start_factor=1.0, end_factor=cfg.lr_final / cfg.lr,
        total_iters=cfg.n_iterations
    )

    # Resume?
    latest = os.path.join(cfg.output_dir, "latest.pt")
    start_iter = 0
    best_reward = float("-inf")
    if os.path.exists(latest):
        print(f"   📂 Resuming from {latest}")
        start_iter, best_reward = load_checkpoint(latest, model, optimizer, scaler)
        print(f"   Resumed at iteration {start_iter}, best_reward={best_reward:.0f}")

    print(f"\n🚀 Starting training: {cfg.n_iterations} iterations, "
          f"{cfg.n_episodes_per_iter} episodes/iter")
    print(f"   Total episodes: {cfg.n_iterations * cfg.n_episodes_per_iter}")
    print(f"   Total steps: {cfg.n_iterations * cfg.n_episodes_per_iter * cfg.rollout_steps:,}")
    print(f"   Device: {device}, FP16: {cfg.fp16}, Workers: {cfg.num_workers}")
    print()

    entropy_coef = cfg.entropy_coef
    distill_coef = cfg.distill_coef
    egregore_coef = cfg.egregore_coef
    total_steps_done = start_iter * cfg.n_episodes_per_iter * cfg.rollout_steps

    # ── Persistent parallel pool (spawn tax paid once) ─────────────────
    pool = None
    if cfg.num_workers > 1:
        try:
            pool = EpisodePool(cfg.num_workers, log=print)
        except Exception as e:
            print(f"[pool] init failed ({type(e).__name__}: {e}); sequential mode")
            pool = None

    def make_seeds(it: int) -> list[int]:
        base = (cfg.seed * 100_003 + it * 9_977) % (2**31)
        return [base + i * 7919 for i in range(cfg.n_episodes_per_iter)]

    # Prime the pipeline: dispatch batch for `start_iter` immediately.
    pending_iter: int | None = None
    if pool is not None and start_iter < cfg.n_iterations:
        model.eval()
        pool.dispatch(model, make_seeds(start_iter), opp_pool_paths)
        pending_iter = start_iter

    for iteration in range(start_iter, cfg.n_iterations):
        # Unfreeze encoder at the boundary
        if iteration == cfg.bc_freeze_iters and cfg.bc_freeze_iters > 0:
            policy_lr = optimizer.param_groups[1]["lr"]
            optimizer.param_groups[0]["lr"] = policy_lr
            print(f"\n   Iter {iteration}: encoder UNFROZEN (all params at lr={policy_lr:.2e})")
        iter_t0 = time.time()

        # ── Phase 1: Rollout Collection (overlapped with prior update) ─
        rollout_t0 = time.time()
        model.eval()

        if pool is not None:
            assert pending_iter == iteration
            trajs = pool.collect()
            pending_iter = None
            batch = assemble(trajs)
        else:
            batch = collect_batch(
                n_episodes=cfg.n_episodes_per_iter,
                model=model,
                device=device,
                base_seed=cfg.seed + iteration * cfg.n_episodes_per_iter,
                deterministic=False,
                opp_pool_paths=opp_pool_paths,
            )

        rollout_time = time.time() - rollout_t0
        total_steps_done += sum(batch["ep_steps"])

        # Rollout stats
        ep_rewards = batch["ep_rewards"]
        ep_money = batch["ep_money"]
        ep_opp = batch["ep_opp_money"]
        ep_steps = batch["ep_steps"]

        wins = sum(1 for m, o in zip(ep_money, ep_opp) if m > o)
        mean_reward = float(np.mean(ep_rewards))
        std_reward = float(np.std(ep_rewards))
        best_ep = float(np.max(ep_rewards))
        worst_ep = float(np.min(ep_rewards))
        mean_money = float(np.mean(ep_money))
        mean_opp = float(np.mean(ep_opp))
        mean_ep_len = float(np.mean(ep_steps))
        steps_per_s = sum(ep_steps) / max(rollout_time, 0.01)

        # Track best
        if mean_reward > best_reward:
            best_reward = mean_reward

        # ── Phase 2: PPO Update (workers already rolling next batch) ───
        # Dispatch next iteration's rollout BEFORE the update so worker
        # compute overlaps GPU update. Snapshot is pre-update theta_i
        # (one-update staleness, APPO-style; PPO clip absorbs the drift).
        if pool is not None and iteration + 1 < cfg.n_iterations:
            pool.dispatch(model, make_seeds(iteration + 1), opp_pool_paths)
            pending_iter = iteration + 1

        train_t0 = time.time()
        model.train()

        entropy_coef *= cfg.entropy_decay

        train_metrics = ppo_update(
            model, optimizer, scaler, batch, iteration, entropy_coef,
            distill_coef, egregore_coef
        )
        distill_coef *= cfg.distill_decay
        egregore_coef *= 0.9995  # slow decay toward 0

        # Update opponent pool
        if (iteration + 1) % cfg.opp_pool_update == 0 and iteration + 1 > 0:
            pool_path = os.path.join(opp_pool_dir, f"iter{iteration:04d}.npz")
            sd = _unwrap_model(model).state_dict()
            np.savez(pool_path, **{k: v.detach().cpu().numpy().astype(np.float32)
                                    for k, v in sd.items()})
            opp_pool_iters.append(iteration)
            opp_pool_paths.append(pool_path)
            # Trim pool
            while len(opp_pool_paths) > cfg.opp_pool_size:
                old = opp_pool_paths.pop(0)
                if os.path.exists(old):
                    os.remove(old)
                opp_pool_iters.pop(0)
            print(f"   ♟️  Opponent pool updated: {opp_pool_iters}")

        train_time = time.time() - train_t0

        scheduler.step()

        # ── Phase 3: Logging ───────────────────────────────────────────
        metrics = {
            "mean_reward": mean_reward,
            "std_reward": std_reward,
            "best_reward": best_reward,
            "worst_reward": worst_ep,
            "mean_money": mean_money,
            "mean_opp_money": mean_opp,
            "mean_ep_len": mean_ep_len,
            "total_steps": total_steps_done,
            "episodes": len(ep_rewards),
            "policy_loss": train_metrics["policy_loss"],
            "value_loss": train_metrics["value_loss"],
            "entropy": train_metrics["entropy"],
            "clip_frac": train_metrics["clip_frac"],
            "distill_loss": train_metrics["distill_loss"],
            "egregore_loss": train_metrics.get("egregore_loss", 0.0),
            "entropy_coef": entropy_coef,
            "lr": optimizer.param_groups[0]["lr"],
            "win_rate": wins / max(len(ep_money), 1),
        }

        timing = {
            "rollout_s": rollout_time,
            "train_s": train_time,
            "iter_s": rollout_time + train_time,
            "steps_per_s": steps_per_s,
        }

        logger.log(iteration, metrics, timing)

        # ── Phase 4: Checkpoint ────────────────────────────────────────
        if iteration % cfg.save_interval == 0 and iteration > 0:
            save_checkpoint(model, optimizer, scaler, iteration, best_reward,
                           cfg.output_dir)
            print(f"   💾 Checkpoint saved (iteration {iteration}, "
                  f"best_reward={best_reward:.0f})")

        # Save best separately only on improvement
        if mean_reward >= best_reward and iteration > 0:
            best_path = os.path.join(cfg.output_dir, "best.pt")
            torch.save({
                "iteration": iteration,
                "model_state": _unwrap_model(model).state_dict(),
                "optimizer_state": optimizer.state_dict(),
                "scaler_state": scaler.state_dict(),
                "best_reward": best_reward,
            }, best_path)

        # ── Phase 5: Periodic Eval (deterministic) ────────────────────
        if iteration % cfg.eval_interval == 0 and iteration > 0:
            eval_model(model, device, iteration, logger)

        # Free GPU cache periodically
        if iteration % 20 == 0 and device.type == "cuda":
            torch.cuda.empty_cache()

    # Drain pipeline: collect the last dispatched batch (discard data)
    if pool is not None and pending_iter is not None:
        try:
            pool.collect()
        except Exception:
            pass
    if pool is not None:
        pool.close()

    # Final checkpoint
    save_checkpoint(model, optimizer, scaler, cfg.n_iterations - 1, best_reward,
                   cfg.output_dir)

    total_time = time.time() - t_start
    print(f"\n✅ Training complete!")
    print(f"   Total time: {total_time / 3600:.1f}h")
    print(f"   Total steps: {total_steps_done:,}")
    print(f"   Best mean reward: {best_reward:.1f}")
    print(f"   Output: {cfg.output_dir}")


def eval_model(model: nn.Module, device: torch.device, iteration: int,
               logger: MetricsLogger | None = None):
    """Benchmark vs pass / rand / mirror + BC solo baseline."""
    model.eval()
    n_groups = cfg.n_actions // 5
    bench = {}

    opp_configs = [
        ("pass", "pass"),
        ("rand", "rand"),
        ("mirror", "mirror"),
    ]
    for label, mode in opp_configs:
        seeds = [2000 + iteration * 37 + i * 13 for i in range(2)]
        moneys, opp_moneys = [], []
        for sd in seeds:
            env = MarketGym(seed=sd, opponent=mode)
            obs = env.reset()
            done = False
            while not done:
                obs_tensor = torch.from_numpy(obs).float().unsqueeze(0).to(device)
                with torch.no_grad():
                    acts, _, _ = model.get_action_md(obs_tensor, deterministic=True)
                obs, reward, done, info = env.step([int(v) for v in acts[0]])
            moneys.append(info["money"])
            opp_moneys.append(info["opp_money"])
        wr = sum(1 for m, o in zip(moneys, opp_moneys) if m > o) / max(len(moneys), 1)
        bench[label] = {
            "money": float(np.mean(moneys)),
            "opp": float(np.mean(opp_moneys)),
            "wr": wr, "n": len(moneys),
        }

    # BC solo score (static reference)
    bc_path = os.path.join(os.path.dirname(cfg.output_dir) or ".", "bc_v9.pt")
    if os.path.exists(bc_path) and not hasattr(eval_model, "_bc_cached"):
        try:
            _bc = TinyTransformer(
                obs_per_step=cfg.obs_per_step, d_model=cfg.d_model,
                n_heads=cfg.n_heads, n_layers=cfg.n_layers,
                seq_len=cfg.seq_len, n_actions=cfg.n_actions,
            ).eval()
            _ck = torch.load(bc_path, map_location="cpu")
            _bc.load_state_dict(_ck["model_state"])
            eval_model._bc_model = _bc.to(device)
            eval_model._bc_cached = True
        except Exception:
            eval_model._bc_model = None
    bc_model = getattr(eval_model, "_bc_model", None)
    if bc_model is not None:
        bc_moneys = []
        for sd in [3000 + iteration * 37 + i * 7 for i in range(2)]:
            env = MarketGym(seed=sd, opponent="pass")
            obs = env.reset()
            done = False
            while not done:
                obs_tensor = torch.from_numpy(obs).float().unsqueeze(0).to(device)
                with torch.no_grad():
                    acts, _, _ = bc_model.get_action_md(obs_tensor, deterministic=True)
                obs, reward, done, info = env.step([int(v) for v in acts[0]])
            bc_moneys.append(info["money"])
        bench["bc_solo"] = {
            "money": float(np.mean(bc_moneys)), "opp": 0, "wr": 1.0, "n": len(bc_moneys),
        }

    # Report
    print(f"\n{'='*65}")
    print(f"  BENCHMARK  iter={iteration}")
    print(f"{'-'*65}")
    for label in ["pass", "rand", "mirror", "bc_solo"]:
        if label not in bench:
            continue
        b = bench[label]
        icon = "PASS" if label == "pass" else ("BC" if label == "bc_solo" else "vs")
        print(f"  {icon:5s} {label:10s}: RL=${b['money']:>10,.0f}  "
              f"Opp=${b['opp']:>10,.0f}  WR={b.get('wr',0):>6.0%}")
    print(f"{'='*65}")

    if logger is not None:
        flat = {"is_eval": True}
        for label, b in bench.items():
            flat[f"bench_{label}_money"] = b["money"]
            flat[f"bench_{label}_opp"] = b["opp"]
            flat[f"bench_{label}_wr"] = b.get("wr", 0)
        logger.log(f"BENCH-{iteration}", flat, {})


# ═══════════════════════════════════════════════════════════════════════
#  ENTRY POINT
# ═══════════════════════════════════════════════════════════════════════
if __name__ == "__main__":
    train()
